// Recebe a resposta da API (lista de contatos) ou o erro da chamada.
// Saída: itens { tipo: 'telegram', text } para você e { tipo: 'email', ... } de boas-vindas para o cliente.
// Guarda o último contato avisado e conta falhas seguidas na memória do fluxo.
const state = $getWorkflowStaticData('global');
const cfg = $('Configuração').first().json;
const r = $input.first().json;

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const out = [];
const telegram = (text) => out.push({ json: { tipo: 'telegram', text } });

const ok = r.statusCode === 200 && Array.isArray(r.body);

if (!ok) {
  // Falha: timeout, API fora, senha errada (401), erro 500...
  const detalhe = r.error?.message || r.error || (r.statusCode ? `HTTP ${r.statusCode}: ${JSON.stringify(r.body).slice(0, 200)}` : 'sem detalhes');
  state.failures = (state.failures || 0) + 1;
  if (state.failures >= cfg.falhasParaAlerta && !state.apiDown) {
    state.apiDown = true;
    telegram(`🚨 <b>Site/API com problema</b>\n${state.failures} verificações seguidas falharam.\n\n<code>${esc(String(detalhe).slice(0, 300))}</code>\n\nPainel: ${esc(cfg.siteUrl)}/admin`);
  }
  return out;
}

if (state.apiDown) telegram(`✅ <b>API voltou</b>\nRespondendo normalmente depois de ${state.failures} verificações com falha.`);
state.failures = 0;
state.apiDown = false;

const contatos = r.body.filter((c) => c && typeof c.id === 'number');
const maxId = contatos.reduce((m, c) => Math.max(m, c.id), 0);

// Primeira execução: só marca onde parou, sem avisar nem mandar e-mail para contatos antigos.
if (state.lastId === undefined) {
  state.lastId = maxId;
  telegram(`🐺 <b>Monitor da Wolf Solutions ligado</b>\nVou te avisar aqui a cada contato novo do site.\nContatos já existentes: ${contatos.length}.`);
  return out;
}
// Banco foi zerado (ids recomeçaram): volta o marcador.
if (maxId < state.lastId) state.lastId = 0;

// ── E-mail de boas-vindas ─────────────────────────────────────────
const primeiroNome = (nome) => {
  const p = String(nome || '').trim().split(/\s+/)[0] || '';
  return p ? p.charAt(0).toUpperCase() + p.slice(1) : '';
};

function emailBoasVindas(c) {
  const nome = primeiroNome(c.name);
  const quiz = c.source === 'quiz';
  const canal = c.whatsapp ? 'pelo WhatsApp ou por este e-mail' : 'por este e-mail';
  const assunto = quiz
    ? `Recebemos seu diagnóstico${nome ? `, ${nome}` : ''} — Wolf Solutions`
    : `Recebemos sua mensagem${nome ? `, ${nome}` : ''} — Wolf Solutions`;
  const paragrafos = quiz
    ? [
        'Obrigado por fazer o diagnóstico de IA da Wolf Solutions e pela confiança em nos contar sobre o seu negócio.',
        `Suas respostas já chegaram até nós. Um especialista da nossa equipe vai analisá-las com atenção e entrar em contato em breve, ${canal}, para mostrar as oportunidades que encontramos — sem compromisso.`,
      ]
    : [
        'Obrigado por entrar em contato com a Wolf Solutions e pela confiança em nos contar sobre o seu negócio.',
        `Sua mensagem já chegou até nós. Um especialista da nossa equipe vai analisá-la com atenção e entrar em contato em breve, ${canal}, para conversar sobre como podemos ajudar — sem compromisso.`,
      ];
  paragrafos.push('Se quiser adiantar a conversa, é só responder este e-mail.');

  const saudacao = nome ? `Olá, ${nome}!` : 'Olá!';
  const p = (t) => `<p style="margin:0 0 16px;font-size:16px;line-height:1.6;color:#3f3d56;">${esc(t)}</p>`;
  const html = `<!DOCTYPE html>
<html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(assunto)}</title></head>
<body style="margin:0;padding:0;background:#f6f5fb;font-family:Arial,Helvetica,sans-serif;">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f6f5fb;padding:32px 12px;"><tr><td align="center">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;background:#ffffff;border-radius:16px;overflow:hidden;border:1px solid #ebe8f5;">
<tr><td style="background:#7c3aed;background-image:linear-gradient(135deg,#7c3aed,#c026d3);padding:28px 32px;">
<span style="font-size:20px;font-weight:bold;color:#ffffff;letter-spacing:0.3px;">Wolf Solutions</span><br>
<span style="font-size:13px;color:#ede9fe;">IA que resolve. Sem complicar o seu negócio.</span>
</td></tr>
<tr><td style="padding:32px;">
<p style="margin:0 0 20px;font-size:20px;font-weight:bold;color:#16141f;">${esc(saudacao)}</p>
${paragrafos.map(p).join('\n')}
<p style="margin:24px 0 0;font-size:16px;line-height:1.5;color:#3f3d56;">Um abraço,<br><strong style="color:#16141f;">${esc(cfg.assinatura)}</strong><br>Wolf Solutions</p>
</td></tr>
<tr><td style="padding:18px 32px;background:#faf9fd;border-top:1px solid #ebe8f5;font-size:12px;line-height:1.5;color:#8a879c;">
Você recebeu este e-mail porque pediu contato pelo site <a href="${esc(cfg.siteUrl)}" style="color:#7c3aed;">${esc(cfg.siteUrl.replace(/^https?:\/\//, ''))}</a>.
</td></tr>
</table></td></tr></table></body></html>`;
  const texto = [saudacao, '', ...paragrafos.flatMap((t) => [t, '']), 'Um abraço,', cfg.assinatura, 'Wolf Solutions'].join('\n');
  return { tipo: 'email', para: c.email, assunto, html, texto };
}

const origem = { quiz: 'Diagnóstico de IA', form: 'Formulário de contato' };
const novos = contatos.filter((c) => c.id > state.lastId).sort((a, b) => a.id - b.id);
const agora = DateTime.now();

for (const c of novos) {
  const criado = DateTime.fromISO(c.created_at);
  const quando = criado.setZone(cfg.fuso).toFormat('dd/MM HH:mm');
  // Só manda boas-vindas para contato recente (se o PC ficou dias desligado, um "recebemos" atrasado soa estranho).
  const enviarEmail = cfg.enviarBoasVindas && !!c.email && agora.diff(criado, 'hours').hours <= cfg.boasVindasAteHoras;

  const linhas = [
    `🔔 <b>Novo contato no site</b> (${esc(origem[c.source] || c.source)})`,
    '',
    `👤 <b>${esc(c.name)}</b>${c.company ? ` — ${esc(c.company)}` : ''}`,
  ];
  if (c.whatsapp) {
    let num = String(c.whatsapp).replace(/\D/g, '');
    if (num.length <= 11) num = '55' + num;
    linhas.push(`📱 WhatsApp: <a href="https://wa.me/${num}">${esc(c.whatsapp)}</a>`);
  }
  if (c.email) linhas.push(`✉️ ${esc(c.email)}`);
  if (c.message) {
    const msg = String(c.message);
    linhas.push('', `💬 ${esc(msg.length > 700 ? msg.slice(0, 700) + '…' : msg)}`);
  }
  if (enviarEmail) linhas.push('', '📨 E-mail de boas-vindas a caminho do cliente (se falhar, te aviso aqui).');
  else if (c.email && cfg.enviarBoasVindas) linhas.push('', '📭 Boas-vindas não enviado (contato antigo — responda você).');
  linhas.push('', `🕒 ${quando} · #${c.id} · <a href="${esc(cfg.siteUrl)}/admin">abrir painel</a>`);
  telegram(linhas.join('\n'));

  if (enviarEmail) out.push({ json: emailBoasVindas(c) });
}

state.lastId = Math.max(state.lastId, maxId);
return out;

// Monta o resumo diário a partir de /api/admin/summary.
const cfg = $('Configuração').first().json;
const s = $input.first().json;
const esc = (v) => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const top = (obj) =>
  Object.entries(obj || {})
    .slice(0, 3)
    .map(([k, v]) => `${esc(k)} (${v})`)
    .join(', ') || '—';

const text = [
  '☀️ <b>Bom dia! Resumo do site</b>',
  '',
  `📥 Contatos: <b>${s.total_contacts}</b> no total — <b>${s.new_contacts}</b> ainda como "novo"`,
  `🧭 Diagnósticos: <b>${s.quiz_last_7_days}</b> nos últimos 7 dias (${s.total_quiz} no total)`,
  `🏷️ Ramos que mais aparecem: ${top(s.by_sector)}`,
  '',
  `Painel: ${esc(cfg.siteUrl)}/admin`,
].join('\n');

return [{ json: { tipo: 'telegram', text } }];

// Se o Gmail recusar o envio, você fica sabendo no Telegram.
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
return $input.all().map((i) => ({
  json: {
    tipo: 'telegram',
    text: `⚠️ <b>Boas-vindas não foi enviado</b> para ${esc(i.json.para)}\n<code>${esc(String(i.json.error?.message || i.json.error || 'sem detalhes').slice(0, 300))}</code>\nResponda esse cliente você mesmo.`,
  },
}));
